<?php
namespace App\Http\Controllers;
use App\Models\Document; use App\Services\ActivityLogService; use Illuminate\Http\Request; use Illuminate\Support\Facades\Storage;
class DocumentFileController extends Controller {
 public function store(Request $request,Document $document){$this->authorize('update',$document);$data=$request->validate(['file'=>['required','file','max:10240','mimes:pdf,doc,docx,xls,xlsx,png,jpg,jpeg']]);$file=$data['file'];$path=$file->store('eoffice/'.$document->uuid,'local');$document->files()->create(['original_filename'=>$file->getClientOriginalName(),'stored_filename'=>basename($path),'disk'=>'local','path'=>$path,'mime_type'=>$file->getMimeType()??'application/octet-stream','size'=>$file->getSize(),'checksum'=>hash_file('sha256',$file->getRealPath()),'uploaded_by'=>$request->user()->id]);ActivityLogService::record($document,'UPLOAD_DOCUMENT_FILE',['filename'=>$file->getClientOriginalName()]);return back()->with('success','Lampiran tersimpan pada storage private.');}
 public function download(Request $request,Document $document){$this->authorize('view',$document);$file=$document->files()->latest()->firstOrFail();abort_unless(Storage::disk($file->disk)->exists($file->path),404);ActivityLogService::record($document,'DOWNLOAD_DOCUMENT',['file_id'=>$file->id]);return Storage::disk($file->disk)->download($file->path,$file->original_filename,['Content-Type'=>$file->mime_type]);}
 public function downloadFinal(Request $request,Document $document){$this->authorize('view',$document);$generated=$document->generatedDocument()->firstOrFail();abort_unless(in_array($document->status,['COMPLETED','ARCHIVED'],true)&&$generated->pdf_path&&Storage::disk('local')->exists($generated->pdf_path),404);ActivityLogService::record($document,'DOWNLOAD_FINAL_DOCUMENT');return Storage::disk('local')->download($generated->pdf_path,($document->number?:$document->uuid).'.pdf',['Content-Type'=>'application/pdf']);}
}
